<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { BookOpenCheck, ChevronRight, Clock3, Compass, EyeOff, Radio, RefreshCw, Search, Sparkles, Star, Users } from '@lucide/vue'
import type { ActivityEvent, Friend, FriendNetwork, World } from './api'
import { buildReunionCards, buildTonightCards, queryLocalSocial, type InsightCard, type LocalQueryResult } from './insights'

const props=defineProps<{friends:Friend[];worlds:World[];events:ActivityEvent[];network:FriendNetwork|null;favoriteIds:string[];storageKey:string;realtimeLabel:string;routeLabel:string;loading:boolean}>()
const emit=defineEmits<{openFriend:[userId:string];openWorld:[worldId:string,location:string];loadNetwork:[];refresh:[]}>()
const query=ref('')
const result=ref<LocalQueryResult|null>(null)
const ignored=ref<string[]>([])
const keep=ref<string[]>([])
const tonight=computed(()=>buildTonightCards(props.friends,props.worlds,props.favoriteIds,props.events))
const reunion=computed(()=>buildReunionCards(props.friends,props.events).filter((item)=>item.targetUserId&&!ignored.value.includes(item.targetUserId)).sort((a,b)=>Number(keep.value.includes(b.targetUserId||''))-Number(keep.value.includes(a.targetUserId||''))||b.score-a.score))
const coverage=computed(()=>new Set(props.events.map((item)=>item.observedAt.slice(0,10))).size)
const onlineCount=computed(()=>props.friends.filter(item=>item.online).length)
const joinableCount=computed(()=>props.friends.filter(item=>item.online&&item.location?.startsWith('wrld_')&&!item.location.includes('~private(')).length)
const knownWorldCount=computed(()=>new Set([...props.worlds.map(item=>item.id),...props.events.map(item=>item.worldId).filter(Boolean)]).size)
function routeType(card:InsightCard){return card.location?'实时可加入':card.reasons.some(item=>item.includes('收藏'))?'收藏/历史建议':card.reasons.some(item=>item.includes('本机记录'))?'历史建议':'热门世界建议'}
function preferenceKey(){return `vrc-harbor-reunion:${props.storageKey}`}
function persist(){localStorage.setItem(preferenceKey(),JSON.stringify({ignored:ignored.value,keep:keep.value}))}
function dismiss(userId?:string){if(!userId)return;ignored.value=[...new Set([...ignored.value,userId])];keep.value=keep.value.filter((id)=>id!==userId);persist()}
function toggleKeep(userId?:string){if(!userId)return;keep.value=keep.value.includes(userId)?keep.value.filter((id)=>id!==userId):[...keep.value,userId];persist()}
function runQuery(value=query.value){query.value=value;if(/跨圈|朋友圈|桥梁/.test(value)&&!props.network){result.value={intent:'loading-network',label:'正在读取本机关系网',cards:[],hint:'只读取 SQLite 中已有的关系快照，不会发起共同好友扫描。'};emit('loadNetwork');return}result.value=queryLocalSocial(value,props.friends,props.worlds,props.events,props.network)}
function open(card:InsightCard){if(card.targetUserId)emit('openFriend',card.targetUserId);else if(card.targetWorldId)emit('openWorld',card.targetWorldId,card.location||'')}
function shortTime(value:string){return new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
onMounted(()=>{try{const value=JSON.parse(localStorage.getItem(preferenceKey())||'{}');ignored.value=value.ignored??[];keep.value=value.keep??[]}catch{ignored.value=[];keep.value=[]}})
watch(()=>props.network,(value)=>{if(value&&result.value?.intent==='loading-network')runQuery(query.value)})
</script>

<template>
  <section class="compass-view wide-view">
    <div class="compass-hero panel"><div><span class="panel-kicker">今晚罗盘</span><h2>现在去哪</h2><p>优先给出实时好友路线；位置不可见时，自动补充收藏、历史与热门世界建议。</p></div><div class="compass-hero-actions"><div class="compass-state"><span><Radio :size="13"/>{{ realtimeLabel }}</span><span>{{ routeLabel }}</span><span>{{ coverage }} 天数据</span></div><button :disabled="loading" @click="emit('refresh')"><RefreshCw :class="{spin:loading}" :size="15"/>{{ loading?'刷新中':'刷新罗盘' }}</button></div></div>
    <div class="compass-coverage panel"><div><b>{{ onlineCount }}</b><span>在线好友</span></div><div><b>{{ joinableCount }}</b><span>公开可加入位置</span></div><div><b>{{ knownWorldCount }}</b><span>已知世界</span></div><div><b>{{ events.length }}</b><span>本机事件</span></div><div><b>{{ network?.edges.length || 0 }}</b><span>关系连线</span></div></div>
    <div class="route-grid"><article v-for="(card,index) in tonight" :key="card.id" class="route-card panel" :data-live="Boolean(card.location)"><header><span>{{ routeType(card) }} · {{ index+1 }}</span><strong>{{ card.score }} 分</strong></header><h3>{{ card.title }}</h3><p>{{ card.summary }}</p><ul><li v-for="reason in card.reasons" :key="reason">{{ reason }}</li></ul><footer><small><Clock3 :size="12"/>建议有效至 {{ shortTime(card.expiresAt) }}</small><button @click="open(card)">查看世界 <ChevronRight :size="14"/></button></footer></article><article v-if="!tonight.length" class="route-empty panel"><Compass :size="27"/><strong>罗盘还没有取得世界数据</strong><span>点击“刷新罗盘”重新读取好友、热门世界和本机历史；不会用缓存位置冒充实时位置。</span><button @click="emit('refresh')"><RefreshCw :size="14"/>立即刷新</button></article></div>
    <div class="compass-columns">
      <article class="query-panel panel"><header><div><Search :size="17"/><strong>问问本机记录</strong></div><small>仅在本机</small></header><form @submit.prevent="runQuery()"><input v-model="query" placeholder="例如：今晚去哪、30 天没见但现在在线的好友"/><button>查询</button></form><div class="query-samples"><button @click="runQuery('今晚去哪')">今晚去哪</button><button @click="runQuery('30 天没见但现在在线的好友')">重逢</button><button @click="runQuery('周五晚上经常遇见谁')">周五晚上</button><button @click="runQuery('连接多个朋友圈的人')">跨圈好友</button><button @click="runQuery('数据覆盖怎么样')">数据覆盖</button></div><section v-if="result" class="query-result"><div><strong>{{ result.label }}</strong><small>{{ result.cards.length }} 条结果</small></div><p v-if="result.hint">{{ result.hint }}</p><button v-for="card in result.cards" :key="card.id" @click="open(card)"><span><strong>{{ card.title }}</strong><small>{{ card.summary }}</small></span><em>{{ card.coverageDays }} 天覆盖</em><ChevronRight :size="14"/></button></section><div v-else class="query-placeholder"><BookOpenCheck :size="22"/><span>可以直接问“今晚去哪”；结果会区分实时路线、历史建议和热门世界。</span></div></article>
      <article class="reunion-panel panel"><header><div><Sparkles :size="17"/><strong>重逢雷达</strong></div><small>{{ reunion.length }} 位候选</small></header><div class="reunion-list"><div v-for="card in reunion" :key="card.id"><button class="reunion-main" @click="open(card)"><span :class="{kept:keep.includes(card.targetUserId||'')}"><Star :size="14"/></span><div><strong>{{ card.title }}</strong><small>{{ card.summary }}</small><em>{{ card.reasons[1] }}</em></div><ChevronRight :size="14"/></button><div class="reunion-actions"><button @click="toggleKeep(card.targetUserId)"><Star :size="12"/>{{ keep.includes(card.targetUserId||'')?'取消关注':'保持联系' }}</button><button @click="dismiss(card.targetUserId)"><EyeOff :size="12"/>暂不提醒</button></div></div><p v-if="!reunion.length">当前没有满足“至少 7 天未记录且现在在线”的好友；数据不足时不会制造候选。</p></div><footer><Users :size="13"/>默认不展示私人位置，偏好只保存在当前浏览器。</footer></article>
    </div>
  </section>
</template>

<style scoped>
.compass-view{display:grid;gap:10px}.compass-hero{display:flex;align-items:flex-end;justify-content:space-between;padding:18px}.compass-hero h2{margin:3px 0;font-size:20px}.compass-hero p{margin:0;color:var(--muted);font-size:9px}.compass-state{display:flex;gap:6px}.compass-state span{display:flex;align-items:center;gap:4px;padding:5px 7px;border:1px solid var(--line);border-radius:5px;color:var(--muted);background:var(--surface-muted);font-size:8px}.route-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.route-card{padding:14px}.route-card header{display:flex;justify-content:space-between;color:var(--muted);font-size:8px}.route-card header strong{color:var(--accent)}.route-card h3{margin:9px 0 4px;font-size:15px}.route-card>p{margin:0;color:var(--ink-soft);font-size:9px}.route-card ul{min-height:58px;margin:11px 0;padding-left:16px;color:var(--muted);font-size:8px;line-height:1.7}.route-card footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding-top:9px}.route-card footer small,.route-card footer button{display:flex;align-items:center;gap:4px;font-size:8px}.route-card footer small{color:var(--muted)}.route-card footer button{border:0;background:transparent;color:var(--accent)}.route-empty{grid-column:1/-1;min-height:170px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted)}.route-empty strong{margin:8px 0 4px;color:var(--ink)}.route-empty span{font-size:9px}.compass-columns{display:grid;grid-template-columns:1.15fr .85fr;gap:10px}.query-panel,.reunion-panel{padding:14px}.query-panel>header,.reunion-panel>header{display:flex;align-items:center;justify-content:space-between}.query-panel>header>div,.reunion-panel>header>div{display:flex;align-items:center;gap:7px}.query-panel header strong,.reunion-panel header strong{font-size:11px}.query-panel header small,.reunion-panel header small{color:var(--muted);font-size:8px}.query-panel form{display:flex;gap:6px;margin-top:12px}.query-panel form input{min-width:0;flex:1;height:36px;padding:0 10px;border:1px solid var(--line);border-radius:6px;background:var(--surface-muted);color:var(--ink);font-size:10px}.query-panel form button{padding:0 13px;border:0;border-radius:6px;background:var(--accent);color:white;font-size:9px}.query-samples{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}.query-samples button{padding:4px 7px;border:1px solid var(--line);border-radius:4px;background:transparent;color:var(--muted);font-size:8px}.query-result{margin-top:12px}.query-result>div{display:flex;justify-content:space-between}.query-result>div strong{font-size:10px}.query-result>div small{color:var(--muted);font-size:8px}.query-result>p{color:var(--muted);font-size:9px;line-height:1.6}.query-result>button{width:100%;display:grid;grid-template-columns:1fr auto 16px;align-items:center;gap:7px;padding:8px 4px;border:0;border-top:1px solid var(--line);background:transparent;color:var(--ink);text-align:left}.query-result>button span{min-width:0}.query-result>button strong,.query-result>button small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.query-result>button strong{font-size:9px}.query-result>button small{margin-top:3px;color:var(--muted);font-size:8px}.query-result>button em{color:var(--muted);font-size:7px;font-style:normal}.query-placeholder{min-height:180px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:var(--muted)}.query-placeholder span{max-width:300px;margin-top:7px;text-align:center;font-size:8px;line-height:1.5}.reunion-list{margin-top:10px}.reunion-list>div{border-top:1px solid var(--line)}.reunion-list>div:first-child{border-top:0}.reunion-main{width:100%;display:grid;grid-template-columns:26px 1fr 16px;align-items:center;gap:6px;padding:8px 2px;border:0;background:transparent;color:var(--ink);text-align:left}.reunion-main>span{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;background:var(--surface-muted);color:var(--muted)}.reunion-main>span.kept{color:var(--warning);background:var(--warning-soft)}.reunion-main div{min-width:0}.reunion-main strong,.reunion-main small,.reunion-main em{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.reunion-main strong{font-size:9px}.reunion-main small{margin-top:2px;color:var(--ink-soft);font-size:8px}.reunion-main em{margin-top:2px;color:var(--muted);font-size:7px;font-style:normal}.reunion-actions{display:flex;justify-content:flex-end;gap:4px;padding:0 2px 6px}.reunion-actions button{display:flex;align-items:center;gap:3px;padding:3px 5px;border:0;border-radius:4px;background:var(--surface-muted);color:var(--muted);font-size:7px}.reunion-list>p{margin:40px 20px;color:var(--muted);text-align:center;font-size:9px;line-height:1.6}.reunion-panel>footer{display:flex;align-items:center;gap:5px;margin-top:8px;padding-top:8px;border-top:1px solid var(--line);color:var(--muted);font-size:8px}@media(max-width:900px){.route-grid{grid-template-columns:1fr}.compass-columns{grid-template-columns:1fr}.compass-hero{align-items:flex-start;gap:12px;flex-direction:column}}@media(max-width:560px){.compass-state{flex-wrap:wrap}.route-card ul{min-height:0}}
.compass-hero-actions{display:flex;align-items:center;gap:8px}.compass-hero-actions>button,.route-empty>button{height:32px;display:flex;align-items:center;gap:5px;padding:0 10px;border:1px solid var(--line);border-radius:6px;background:var(--surface-muted);color:var(--ink-soft);font-size:11px;cursor:pointer;white-space:nowrap}.compass-hero-actions>button:disabled{opacity:.55}.compass-coverage{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));padding:9px}.compass-coverage>div{display:flex;align-items:baseline;justify-content:center;gap:6px;min-height:38px;border-right:1px solid var(--line)}.compass-coverage>div:last-child{border:0}.compass-coverage b{color:var(--accent);font-size:18px}.compass-coverage span{color:var(--muted);font-size:11px}.route-card[data-live=true]{border-color:color-mix(in srgb,var(--accent) 35%,var(--line));box-shadow:inset 0 3px 0 color-mix(in srgb,var(--accent) 75%,transparent)}.route-card h3{font-size:17px}.route-card>p{font-size:12px;line-height:1.55}.route-card ul{font-size:11px}.route-card footer small,.route-card footer button{font-size:10px}.route-empty>span{max-width:620px;font-size:11px;line-height:1.6;text-align:center}.route-empty>button{margin-top:12px}
@container (max-width:1000px){.compass-coverage{grid-template-columns:repeat(3,minmax(0,1fr))}.compass-coverage>div:nth-child(3){border-right:0}.compass-hero-actions{align-items:flex-end;flex-direction:column}}
@container (max-width:650px){.compass-coverage{grid-template-columns:repeat(2,minmax(0,1fr))}.compass-coverage>div:nth-child(3){border-right:1px solid var(--line)}.compass-coverage>div:nth-child(even){border-right:0}.compass-hero-actions{width:100%;align-items:stretch}.compass-hero-actions>button{justify-content:center}.compass-state{flex-wrap:wrap}}
</style>
